function paletteLabel(){$('[data-action=palette]').textContent=document.documentElement.dataset.style==='paper'?'切换夜场':'切换奶油';}paletteLabel();const brandMark=$('.brand>i');if(brandMark){brandMark.outerHTML=`<img class="brand-logo" src="${window.WORLD_BRANDING.logo}" alt="镜面双我Logo">`;}
const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('width','0');svg.setAttribute('height','0');svg.style.position='absolute';svg.setAttribute('aria-hidden','true');svg.innerHTML='<defs></defs>';document.body.appendChild(svg);
function ensureSheet(id,s){if(document.getElementById(id))return;const el=document.createElementNS('http://www.w3.org/2000/svg','image');el.setAttribute('id',id);el.setAttribute('width',s.width);el.setAttribute('height',s.height);el.setAttribute('href',s.url);el.setAttributeNS('http://www.w3.org/1999/xlink','xlink:href',s.url);svg.firstChild.appendChild(el);}
function pruneSheets(){const used=[];document.querySelectorAll('#app use,#dialog[open] use').forEach(el=>used.push(el.getAttribute('href')));Array.from(svg.firstChild.children).forEach(el=>{if(!used.includes('#'+el.id))el.parentNode.removeChild(el);});}

function themed(id=theme){return D.themes.find(t=>t.id===id);}function person(id){return D.characters.find(p=>p.id===id)||(currentRecord?recordData(currentRecord).characters.find(p=>p.id===id):null);}
function seriesName(){return theme==='lol'?'英雄联盟 · 综合题库':themed().name;}
function portrait(p,extra=''){const id=typeof p==='string'?p:p.personId,name=typeof p==='string'?'宇宙灰狼':p.name,m=window.WORLD_PORTRAITS[id];if(!m||m.pending)return `<span class="portrait pending-portrait" data-avatar="${esc(id)}" role="img" aria-label="${esc(name)}头像待核实"><b>${esc(name.slice(0,2))}</b><small>参考图核对中</small></span>`;const s=window.WORLD_ATLASES[m.sheet],w=s.width/2,h=s.height/2;ensureSheet('atlas-'+m.sheet,s);return `<span class="portrait cartoon ${extra}" data-avatar="${esc(id)}" role="img" aria-label="${esc(name)}卡通头像"><svg viewBox="${m.cell%2*w} ${Math.floor(m.cell/2)*h} ${w} ${h}" aria-hidden="true"><use href="#atlas-${m.sheet}" xlink:href="#atlas-${m.sheet}"/></svg><span class="portrait-load-fallback" aria-hidden="true">${esc(name.slice(0,2))}</span></span>`;}
function perkIcon(a){if(a.visual){return `<span class="perk-art equipment-mix" role="img" aria-label="${esc(a.visual.label)}，真实游戏图标梗改" data-layout="${a.visual.layout}" data-copies="${a.visual.icons.length}">${E.artLayout(a).map((p,i)=>`<img class="game-item" data-game-icon="${p.icon}" data-copy="${i+1}" src="${window.WORLD_GAME_ICONS[p.icon].url}" alt="" style="--ix:${p.x*100}%;--iy:${p.y*100}%;--is:${p.size*100}%;--ir:${p.rotation}deg">`).join('')}</span>`;}const meta=a.classicSprite||{sheet:0,cell:a.icon||0},s=(window.WORLD_PERK_SHEETS||[window.WORLD_PERK_SHEET])[meta.sheet]||window.WORLD_PERK_SHEET,w=s.width/4,h=s.height/4,i=meta.cell;ensureSheet('perk-sheet-'+meta.sheet,s);return `<span class="perk-art rich-perk-art" role="img" aria-label="${esc(a.name)}棱彩漫画图标"><svg viewBox="${i%4*w} ${Math.floor(i/4)*h} ${w} ${h}" aria-hidden="true"><use href="#perk-sheet-${meta.sheet}" xlink:href="#perk-sheet-${meta.sheet}"/></svg></span>`;}

function personLabel(id){const p=D.characters.find(c=>c.theme===theme&&c.personId===id);return p?(p.nickname||p.name):'';}
function findCard(id){const pools=[D,window.WORLD_V13_DATA,window.WORLD_V12_DATA,window.WORLD_V11_DATA,window.WORLD_LEGACY_DATA];for(const d of pools){if(!d)continue;const a=[].concat(...Object.values(d.augments)).find(a=>a.id===id);if(a)return a;}return null;}
function render(html){
 clearTimeout(answerTimer);answerTimer=null;advancing=false;
 document.body.classList.toggle('is-home',html.includes('v14-home'));
 document.body.classList.toggle('has-dock',html.includes('result-dock'));
 document.body.classList.toggle('focus-mode',/intro-page|reveal-page|class="quiz|v14-story/.test(html));
 app.innerHTML=html+(!persistent?'<p class="local-note">当前环境不保存记录，本次体验和导出仍可使用。</p>':'');
 app.focus({preventScroll:true});scrollTo(0,0);requestAnimationFrame(()=>scrollTo(0,0));document.documentElement.style.setProperty('--accent',themed().accent);
 document.documentElement.dataset.appReady='true';$('#loading').hidden=true;pruneSheets();
 document.querySelectorAll('#tabbar [data-action]').forEach(b=>b.setAttribute('aria-current',html.includes('v14-home')&&b.dataset.action==='home'?'page':html.includes('archive')&&b.dataset.action==='archive'?'page':'false'));
}
function recordData(record){return record&&record.session.version===10?window.WORLD_LEGACY_DATA:record&&record.session.version===11?window.WORLD_V11_DATA:record&&record.session.version===12?window.WORLD_V12_DATA:record&&record.session.version===13?window.WORLD_V13_DATA:D;}
function recordEngine(record){return record&&record.session.version===10?window.ShenrenLegacyEngine:record&&record.session.version===11?window.ShenrenV11Engine:record&&record.session.version===12?window.ShenrenV12Engine:record&&record.session.version===13?window.ShenrenV13Engine:E;}
function analyzeRecord(record){
 const r=recordEngine(record).analyze(record.session,recordData(record));
 const rd=recordData(record),re=recordEngine(record);
 if(rd.branchStories&&typeof re.storyValid==='function'){
  const bs=storyFor(r.identity.personId,rd);let view=null;
  if(record.storyState&&record.storyState.originKey===record.id&&re.storyValid(record.storyState,rd))view=re.storyView(record.storyState,rd);
  r.obtainedCardIds=view?view.ownedCardIds:(r.obtainedCardIds||[r.augment.id]);
  r.obtainedCards=r.obtainedCardIds.map(id=>[].concat(...Object.values(rd.augments)).find(a=>a.id===id)).filter(Boolean);
  if(bs)r.story=[view&&view.isEnding?view.title:bs.title,view&&view.isEnding?view.text:bs.nodes[0].text,'你的选择会改变后面的场面。'];
 }
 return r;
}
function history(){const v=read('history',[]);return Array.isArray(v)?v.filter(r=>r&&recordEngine(r).valid(r.session,recordData(r),true)).slice(0,12):[];}function pending(){const s=read('session');return E.valid(s,D)?s:null;}
