window.addEventListener('popstate',function(){if(panelBackPending){panelBackPending--;return;}if(!browserPanel)return;browserPanel=false;if(library&&library.stack.length>1){library.stack.pop();libraryView(true);try{window.history.pushState({v14Panel:true},'');browserPanel=true;}catch(_){}}else close(true);});
modal.addEventListener('cancel',function(e){e.preventDefault();libraryBackOrClose();});
function libraryBackOrClose(){if(library&&library.stack.length>1)libraryBack();else close();}
modal.addEventListener('keydown',function(e){if(e.key==='Escape'){e.preventDefault();libraryBackOrClose();return;}if(e.key!=='Tab')return;const focusable=Array.from(modal.querySelectorAll('button:not([disabled]),input,select,a[href],[tabindex="0"]')).filter(el=>el.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
const journeyTitles=['普通的一天','镜子慢了半拍','另一种人生'];
