function libraryCapture(){if(library&&library.stack.length){const v=library.stack[library.stack.length-1],el=document.activeElement;v.scroll=modal.scrollTop;if(el&&el.dataset){v.focusAction=el.dataset.action;v.focusId=el.dataset.id;}}}
